const support = 'Mixed-level support: model a short response first; allow keywords and sentence starters, then invite a fuller attempt. Stretch: justify choices or extend the response without a script. Pupils may use invented personal details. No student device, external recording or worksheet is required; notebooks and a board are sufficient.';
const frame = (title, mode, lines, extra = {}) => ({ title, mode, lines, ...extra });
function stage(id, title, durationMinutes, notes, frames, start) {
  const seconds = durationMinutes * 60;
  frames.forEach((f, i) => { f.timerSeconds ??= Math.floor(seconds / frames.length) + (i === frames.length - 1 ? seconds % frames.length : 0); f.expectedSeconds = f.timerSeconds; });
  return { id, title, durationMinutes, timeRange: `${start}–${start + durationMinutes} min`, notes: `${notes}\n${support}`, frames };
}

export const ieltsLessons = cards.map((c, index) => ({
  id: `g7-ielts-${String(index + 1).padStart(2, '0')}`,
  title: c.title, durationMinutes: 45, coreMinutes: 45, contentRevision: 1,
  ielts: true, classroomOnly: true, customVisuals: true,
  eyebrow: `Grade 7 · IELTS Preparation · Lesson ${index + 1}`,
  catalog: { subjectId: 'ielts', grades: [7], classes: ['7a', '7b'], unit: `${c.skill} · Lesson ${index + 1} of 30`, order: index + 1 },
  openingScript: `Today: ${c.goal} This is original IELTS Academic foundation practice for Grade 7. Use the same lesson in 7A and 7B; progress is saved separately by class. ${support}`,
  stages: [
    stage('begin', 'Connect and set a goal', 5, `Ask the starter, give quiet thinking time, then hear two examples. Introduce the goal: ${c.goal}`, [
      frame('Start with your experience', 'think', [c.starter]),
      frame('Today’s goal', 'listen', [c.goal, 'Notice the strategy. Try it. Check it. Improve it.'])
    ], 0),
    stage('teach', 'Learn the strategy', 8, `Model the strategy with the supplied example. Check understanding after each step. ${c.notes}`, [
      ...c.teach.map((line, i) => frame(`Strategy ${i + 1}`, 'listen', [line]))
    ], 5),
    stage('model', 'Try the worked example', 8, `Keep the response hidden until pupils have attempted the task. Ask for evidence, then reveal and compare. ${c.notes}`, [
      frame(c.skill === 'Listening' ? 'Prepare to listen' : 'Read the practice material', 'think', [c.source]),
      frame(c.question, 'think', ['Attempt the task before revealing the model.'], { type: 'question', answerText: 'Model and explanation', explanation: c.model, sourceCard: c.source })
    ], 13),
    stage('apply', 'Practise and transfer', 14, `First task: 6 minutes, including role swap or peer check. New task: 8 minutes, including independent work and a brief comparison. For Listening, use the second script here. ${c.notes}`, [
      frame('Practise together', 'pair', [c.task], { sourceCard: c.source, timerSeconds: 360 }),
      frame('Try a new example', 'think', [c.transfer], { timerSeconds: 480 })
    ], 21),
    stage('check', 'Check and improve', 7, `Give two minutes for an individual answer, two for comparison, and three to explain and revise. Accept alternative open responses that meet the stated criteria. ${c.notes}`, [
      frame(c.check, 'think', ['Give your answer and explain your evidence or reasoning.'], { type: 'question', answerText: 'Check your reasoning', explanation: c.key, sourceCard: c.transfer }),
      frame('Improve one response', 'pair', ['Choose one answer or sentence to improve.', 'Explain what changed and why it works better.'])
    ], 35),
    stage('finish', 'Exit ticket and next step', 3, 'Collect one specific response from every pupil in notebooks or a brief partner exchange. Use the responses to decide which lesson or skill to teach next. Classroom times are estimates; optional extension: repeat independently with a new example.', [
      frame('Show what you learned', 'think', [c.exit, 'Name one strategy you can use again.'], { final: true })
    ], 42)
  ]
}));
